// ❌ BAD STATE SHAPE (Redundant data)
const state = {
  todos: [{ id: 1, done: true }, { id: 2, done: false }],
  completedTodosCount: 1 // NEVER DO THIS!
}

// ✅ GOOD PATTERN (Derived State via Selector)
// The state only holds the raw array.
// The selector computes the count on the fly!
export const selectCompletedCount = (state) => {
  return state.todos.filter(todo => todo.done).length;
};
